/* From Uiverse.io by AKAspidey01 - Tags: button, arrow */
.__UIV_SCOPE__ .button {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 15px;
  border-radius: 10px;
  border: none;
  overflow: hidden;
  background: rgb(164, 46, 194);
  color: #fff;
}

.__UIV_SCOPE__ .button-text {
  transform: translateX(15px);
  font-size: 1.5em;
  font-weight: 700;
  transition-duration: 0.3s;
}

.__UIV_SCOPE__ .iconer {
  transform: translateY(35px);
  transition-duration: 0.3s;
}

.__UIV_SCOPE__ .button:hover .button-text {
  transform: translateX(0px);
}

.__UIV_SCOPE__ .button:hover .iconer {
  transform: translateY(0px);
}
